"""Layer 15 MLP hidden unit 5190, read off through its down_proj component.

The component is almost exactly one hidden unit of the layer-15 MLP (its input
direction is that unit, weight about 1.0), scaled by about 1.2. The unit is
sparse and heavy-tailed: most tokens sit near 0, and a few kinds of word push it
up. No single concept covers it, so this program names the word groups it
responds to most, and predicts 0 everywhere else.

Word groups, strongest first (typical activation in brackets):
- The test-result word PASS, as in "--- PASS: TestX" (about 10), and the
  "SED" of a PASSED split as " PAS" + "SED" (about 6).
- Other test and log status words: FAIL, RUN, INFO, Warning (about 3 to 5).
- Month names, full and abbreviated (about 4.5), and compass directions
  north, south, east, west (about 4.5).
- Weekday names (about 3.5).
- Trend words increase and decrease (about 3).
- C-style literals void, int, bool, false, true (about 1.5).

This captures only a few percent of the variance. The remainder is spread over
thousands of tokens and contexts with no simple name. A full token lookup
table would capture about 12% out of sample, but it would not be readable.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MONTHS = {
    "January", "February", "March", "April", "May", "June", "July", "August",
    "September", "October", "November", "December",
    "Jan", "Feb", "Mar", "Apr", "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec",
}
WEEKDAYS = {
    "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday",
    "Mon", "Tue", "Tues", "Wed", "Thu", "Thur", "Fri", "Sat", "Sun",
}
COMPASS = {"north", "south", "east", "west"}
STATUS = {"FAIL", "RUN", "INFO", "Warning", "warning"}
TREND = {"increase", "increases", "increased", "decrease", "decreases", "decreased"}
C_LITERALS = {"void", "int", "bool", "false", "true"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if word == "PASS":
        value = 10.0
    elif word == "SED" and before == "PAS":
        value = 6.0
    elif word in STATUS:
        value = 3.5
    elif word in MONTHS or word in COMPASS:
        value = 4.5
    elif word in WEEKDAYS:
        value = 3.5
    elif word in TREND:
        value = 3.0
    elif word in C_LITERALS:
        value = 1.5
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down_proj, component 5202: the "seeing and showing" verb feature.

It fires on verbs about sight and display, used as verbs: see / saw / seen, show /
shows / showed / shown, and look / looked / watch / observe / notice. It is weaker on
check, view, appear and seem, and on sight verbs in other languages (看, 見, вид, vedere).
Nouns such as "the show" or "a unique look" stay near zero.

Its output direction points at visual nouns (pictures, screens, footage), so it marks a
spot where something visual is about to be named. It is also strong on the word right
after "look" ("look AT"), and mildly on the word right after another sight verb
("see THE", "show HOW"). Everything else is about zero.
"""

READS = ()

SEE = {"see", "sees", "saw", "seen", "seeing"}
SHOW = {"show", "shows", "showed", "shown", "showing", "demonstrate", "demonstrates",
        "demonstrated", "illustrate", "illustrates", "illustrated"}
LOOK = {"look", "looks", "looked", "looking", "watch", "watched", "observe", "observed",
        "notice", "noticed"}
WEAK = {"check", "view", "appear", "appears", "appeared", "seem", "seems", "seemed"}
FOREIGN = {"看", "看到", "看看", "看着", "见", "見", "を見", "보", "вид", "показ", "vedere",
           "voir", "mostrar", "zeigt", "nhìn"}
SIGHT_VERBS = SEE | SHOW | LOOK
FUNCTION_AFTER = {"the", "a", "how", "out", "them", "me", "you", "in", "of"}


def word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    if w in SEE:
        value = 16.0
    elif w in SHOW:
        value = 13.0
    elif w in LOOK:
        value = 8.0
    elif w in WEAK or w in FOREIGN:
        value = 5.5
    else:
        value = 0.0
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc and word(prefix.token_strings[-2]) in SIGHT_VERBS:
        if w == "at":
            value = 14.0
        elif w in FUNCTION_AFTER:
            value = 5.0
    return carry, value

"""Component 5207 of layers.15.mlp.down_proj: a "value in a formula or code" detector.

The component is mostly quiet, but where it speaks it is negative, and the strongest
negative values are on the values written inside formulas and code:
  - boolean and null literals (true, false, None, null, nil, undefined): about -4,
  - digits and single letters (variables) that sit right after a math operator
    (a = 2 + x, E[a+1, b]): about -2,
  - digits and letters inside a dense run of math or code symbols.
Ordinary digits and letters in prose are near zero. Underscore identifiers (__init__,
_editor) are mildly positive, as is Chinese/Japanese text. The program reads only the tokens
up to the current one, and resets at each document start.
"""

READS = ()

LITERALS = {"true", "false", "null", "none", "nil", "undefined", "nullptr"}
OPERATORS = {"+", "-", "*", "/", "=", "^", "×", "−", "≤", "≥", "≠", "%", "<", ">", "**", "=="}
MATH_CHARS = set("+-*/=^<>×−≤≥≠%√²")
WINDOW = 16


def is_digit(s):
    return len(s) == 1 and s.isdigit()


def is_letter(s):
    return len(s) == 1 and s.isascii() and s.isalpha()


def is_cjk(s):
    return any("぀" <= c <= "鿿" for c in s)


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0:
        return carry, 0.0
    word = prefix.token_strings[t].strip()
    doc = prefix.document_ids[t]
    start = t
    while start > 0 and prefix.document_ids[start - 1] == doc and t - start < WINDOW:
        start -= 1
    recent = [prefix.token_strings[i].strip() for i in range(start, t)]
    prev = recent[-1] if recent else ""
    near = recent[-8:]
    dense8 = sum(any(c in MATH_CHARS for c in s) for s in near) / max(1, len(near))
    dense16 = sum(any(c in MATH_CHARS for c in s) for s in recent) / max(1, len(recent))
    after_op = prev in OPERATORS
    value = -1.0 * dense16
    if word in LITERALS:
        value += -4.0 - 1.9 * dense8
    elif is_digit(word):
        value += -0.35 - 0.4 * after_op - 2.7 * dense8
    elif is_letter(word):
        value += -0.2 - 1.6 * after_op
    elif "__" in word:
        value += 1.0
    elif is_cjk(word):
        value += 0.12
    return carry, value

"""Layer 15 MLP hidden unit 5216, read as a contrast detector.

This component's input direction is dominated by that one MLP hidden unit (weight 0.71; the next
largest weight is 0.06), so it tracks that unit's activation. It is largest on adversative
connectives that turn an argument around: "but" (mean about 1.1, much higher where an expectation
was set up and then failed), "Yet", "however", "yet", "whereas", "instead", and their translations.
It is negative on concession words such as "despite", "notwithstanding" and "unless", and mildly
negative on "than". Most of its variance is diffuse: it sits on very common tokens with no
consistent sign, and token identity explains only about 3% of it, so this program captures only the
contrast pattern and explains about 1% of the variance.
"""

READS = ()

CONTRAST = {
    "but", "yet", "however", "whereas", "nevertheless", "nonetheless", "instead",
    "但是", "可是", "然而", "却", "卻", "しかし", "けど", "だが", "のに",
    "nhưng", "pero", "maar", "aber", "doch", "но", "однако", "지만", "แต่",
}
CONCESSION = {"despite", "notwithstanding", "unless", "forget", "blame", "deny", "ignoring"}


def word(s):
    return s.strip().strip(".,;:!?\"'“”’").lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = word(s)
    if w in CONTRAST or s.strip() in CONTRAST:
        return carry, 1.0
    if w in CONCESSION:
        return carry, -0.5
    if w == "than":
        return carry, -0.3
    return carry, 0.0

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:5219 (layer 15 MLP, down_proj).

What it does: it fires on the word "of" (and its foreign twins "de", "di", "của",
"ของ"), the preposition that opens a partitive or "of-complement" phrase. How strongly
it fires depends on the word just before "of":

- a quantity word that takes "of" as a partitive ("all of", "most of", "none of",
  "both of", "some of", "each of", "two of" ...) -> strong;
- a partitive noun ("one of", "part of", "number of", "lot of", "end of" ...) -> medium;
- a word where "of" is not a partitive ("out of", "because of", "instead of", "kind of",
  "use of" ...) -> weak;
- any other "of" -> medium-high.

Everywhere else it is about zero. Its output direction, read through the unembedding,
promotes "these", "this", "estas" and similar determiners: after "all of" it pushes
toward "these" / "them", the next word of a partitive phrase.

The program only reads the current token and the one before it (within the same
document), so it needs no carried state.
"""

READS = ()

# "of" as a preposition, in its English spellings
OF_WORDS = {"of", "OF", "Of"}

# Prepositions "de", "di", "của", "ของ" that play the same role in other languages
OF_FOREIGN = {"de", "di", "del", "des", "da", "do", "của", "ของ", "dell", "delle", "du"}

# Quantity words that head a partitive: "all of", "most of", "none of", ...
QUANTITY = {
    "all", "most", "some", "none", "both", "each", "many", "few", "any", "several",
    "either", "neither", "two", "three", "four", "five", "half", "majority",
    "fraction", "percentage", "portion", "portions", "rest", "more",
}

# Partitive nouns: "one of", "part of", "number of", "lot of", "end of", ...
PARTITIVE_NOUNS = {
    "one", "part", "number", "lot", "top", "end", "series", "variety", "members",
    "types", "set", "group",
}

# Words after which "of" is usually not partitive: "out of", "because of", ...
NON_PARTITIVE = {"out", "because", "instead", "kind", "sort", "use", "lack", "that", "as"}


def _word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    if cur in OF_WORDS:
        if prev in QUANTITY:
            value = 3.5
        elif prev in PARTITIVE_NOUNS:
            value = 1.5
        elif prev in NON_PARTITIVE:
            value = 0.5
        else:
            value = 1.8
    elif cur in OF_FOREIGN:
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

"""Possession detector for layer 15's MLP unit 5231.

The unit is active on words that say something HAS, CONTAINS, OWNS or COMES WITH something:
  - verbs of containing and owning ("contains", "comprises", "possesses", "carries",
    "includes", "consists of", "equipped") are strongest (about 9);
  - have / has / had / having, and "with" meaning "having" (about 3 to 4.5);
  - the word right after such a verb when it opens the object: "has THE", "contain A" (about 3 to 5);
  - "comes with", "equipped with" make "with" strong; "with" in "along with", "compliance with" is off;
  - the same verbs in French, German, Spanish, Russian, Chinese and Portuguese count too;
  - the end-of-text token is strongly negative (about -11), and "import" a little negative.
Everything else is 0. Context is reset at each document start.
"""
READS = ()

# Verbs of containing, owning, comprising (strongest).
STRONG = {"contain", "contains", "containing", "contained", "comprise", "comprises", "comprising",
          "comprised", "possess", "possesses", "possessing", "possessed", "owns", "owned", "owning",
          "boasts", "carry", "carries", "carrying", "carried", "consist", "consists", "consisting",
          "consisted", "equipped", "bearing", "lacks", "lacking",
          "含有", "拥有", "具有", "具备", "带有", "包含", "有着", "tiene", "tienen", "possui",
          "имеет", "имеют", "содержит"}
# Have-verbs, and "with" when it means "having" (the value is set separately).
MID = {"have", "has", "had", "having", "hold", "holds", "holding", "includes", "include", "included",
       "including", "with", "mit", "avec", "有", "带", "含", "есть", "có"}
# Words that start a possessed object after a verb ("has the", "contains a").
DETS = {"a", "an", "the", "some", "no", "any", "all", "both", "this", "its", "their", "his", "her",
        "our", "your", "my"}
# What makes "with" a possession sense: "comes with", "equipped with", "provided with".
WITH_OBJ = {"comes", "come", "equipped", "provided", "filled", "covered", "endowed", "imbued"}
END = "<|endoftext|>"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word == END:
        return carry, -11.0
    if prev in STRONG or (prev in MID and prev != "with"):
        if word == "the":
            return carry, 5.0
        if word in DETS:
            return carry, 3.3
    if word in STRONG:
        return carry, 9.0
    if word == "with":
        return carry, 9.5 if prev in WITH_OBJ else 3.3
    if word in MID:
        return carry, 4.5
    if word == "import":
        return carry, -1.9
    return carry, 0.0

"""Layer 15 MLP, down_proj component 5232.

What it does: this component is essentially one MLP hidden unit of layer 15 (unit 5232),
read off as its contribution to the residual stream. It goes negative on the words that
attach a modifier to the noun just before them. The strongest cases are the wh-words
(who, whom, whose, where: about -2.5), then participles (having, containing, involving:
about -1.5), then "which" (about -0.8, or -2.5 after a quantity or place noun) and "that"
(about -0.8 after a thing or person noun, -0.2 otherwise). "with" is about -1.4 after a
thing or person noun and -0.6 otherwise; "for" is about -0.5. "of" is about -1.2 after a
person or group noun ("the owner of", "author of", "mother of"), about +0.3 after an
abstract noun ("process of", "state of") and 0 otherwise. Everything else sits near its
typical value of about +0.1.

The context rules use WordNet's lexicographer categories of the previous word. Most of the
variance is diffuse and depends on context a word list cannot see, so the fit is weak.
"""

from functools import lru_cache

import wordnet

READS = ()

BASE = 0.1
"""The typical activation of an unlisted token."""
WH_WORDS = {" who", " whom", " whose", " where", " whereby", " wherein"}
PARTICIPLES = {" having", " containing", " comprising", " featuring", " involving", " requiring"}
PERSON_OR_THING = {"noun.person", "noun.group", "noun.location", "noun.artifact", "noun.animal",
                   "noun.food", "noun.substance", "noun.Tops", "noun.body"}
PERSON_OR_GROUP = {"noun.person", "noun.group"}
QUANTITY_OR_PLACE = {"noun.quantity", "noun.location"}
ABSTRACT = {"noun.process", "noun.state", "noun.feeling", "noun.phenomenon", "noun.event",
            "noun.attribute", "noun.cognition", "noun.communication"}


@lru_cache(maxsize=None)
def categories(word):
    """WordNet's lexicographer categories of a word, or none if it is not an English word."""
    word = word.strip().lower()
    return wordnet.categories(word) if word.isalpha() else frozenset()


def predict(word, previous):
    """This component's activation at a token `word`, after the token `previous` (or '')."""
    if word in WH_WORDS:
        return -2.5
    if word in PARTICIPLES:
        return -1.5
    cats = categories(previous)
    if word == " which":
        return -2.5 if cats & QUANTITY_OR_PLACE else -0.8
    if word == " that":
        return -0.8 if cats & PERSON_OR_THING else -0.2
    if word == " with":
        return -1.4 if cats & PERSON_OR_THING else -0.6
    if word == " for":
        return -0.5
    if word == " of":
        if cats & PERSON_OR_GROUP:
            return -1.2
        return 0.3 if cats & ABSTRACT else 0.0
    if word == " to":
        return 0.0
    return BASE


def step(carry, prefix, upstream):
    """Predict this component's activation at the newest token."""
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = prefix.token_strings[-2] if same_doc else ""
    return carry, float(predict(prefix.token_strings[-1], previous))

"""Copula detector for MLP hidden unit 5235 of layers.15.mlp.down_proj.

What it does, in plain terms: this component goes negative on a form of "to be"
(is, are, was, were, be, been, being, am) when the verb is about to introduce a predicate:
a passive participle ("can be [used]", "is [determined]") or a technical adjective
("is [largest]"). It is most negative right after a modal ("can be", "may be", "must be") and
after "to" ("to be"). After a pronoun or wh-word ("it is", "this is", "what is", "there is")
it is much weaker. The contraction "'s" and linking words ("seems", "became", "very") lean
positive, and "a" slightly so. Every other token predicts 0.

The magnitudes are rounded group means measured on training rows; nothing else is fitted.
"""

READS = ()

COPULA = {" is", " are", " was", " were", " be", " been", " being", " am",
          " Is", " Are", " Was", " Were", " Be", " Been", " Being"}
MODALS = {" can", " may", " must", " should", " will", " could", " shall", " might", " would",
          " cannot"}
PRONOUNS_AND_WH = {
    " it", " It", " this", " This", " that", " That", " there", " There", " here", " Here",
    " what", " What", " which", " Which", " who", " these", " those", " he", " He", " she",
    " She", " they", " They", " you", " You", " I", " we",
}
LINKING_OR_DEGREE = {" seems", " seem", " seemed", " became", " become", " remained",
                     " considered", " known", " very", " really", " quite", " fairly",
                     " extremely", " incredibly", " relatively", " somewhat"}
CONTRACTED_IS = {"'s", "’s"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    if token in COPULA:
        if before in MODALS:
            value = -2.5
        elif before == " to":
            value = -1.5
        elif before in PRONOUNS_AND_WH:
            value = -0.5
        else:
            value = -1.8
    elif token in CONTRACTED_IS:
        value = 0.35
    elif token in LINKING_OR_DEGREE:
        value = 0.5
    elif token in {" a", " an"}:
        value = 0.15
    elif token == " not":
        value = -0.2
    else:
        value = 0.0
    return carry, value
